.darma-loader-darma-b7-infinity-trace { --accent: var(--loader-color, #ec4899); --accent-2: var(--loader-secondary-color, #8b5cf6); width: var(--loader-size, 96px); height: calc(var(--loader-size, 96px) * .5); position: relative; }
.darma-loader-darma-b7-infinity-trace::before, .darma-loader-darma-b7-infinity-trace::after { content: ''; position: absolute; top: 50%; width: calc(var(--loader-size, 96px) * .5); height: calc(var(--loader-size, 96px) * .5); margin-top: calc(var(--loader-size, 96px) * -.25); border: calc(var(--loader-size, 96px) * .045) solid color-mix(in srgb, var(--accent-2) 35%, transparent); border-radius: 50%; box-sizing: border-box; }
.darma-loader-darma-b7-infinity-trace::before { left: 0; }
.darma-loader-darma-b7-infinity-trace::after { right: 0; }
.darma-loader-darma-b7-infinity-trace span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size, 96px) * .14); height: calc(var(--loader-size, 96px) * .14); margin: calc(var(--loader-size, 96px) * -.07) 0 0 calc(var(--loader-size, 96px) * -.07); border-radius: 50%; background: var(--accent); box-shadow: 0 0 calc(var(--loader-size, 96px) * .12) var(--accent); animation: darma-loader-darma-b7-infinity-trace-infinity calc(var(--loader-speed, 1s) * 2.2) linear infinite; }
@keyframes darma-loader-darma-b7-infinity-trace-infinity { 0% { transform: translate(calc(var(--loader-size, 96px) * .25), 0); } 12.5% { transform: translate(calc(var(--loader-size, 96px) * .177), calc(var(--loader-size, 96px) * -.125)); } 25% { transform: translate(0, 0); } 37.5% { transform: translate(calc(var(--loader-size, 96px) * -.177), calc(var(--loader-size, 96px) * .125)); } 50% { transform: translate(calc(var(--loader-size, 96px) * -.25), 0); } 62.5% { transform: translate(calc(var(--loader-size, 96px) * -.177), calc(var(--loader-size, 96px) * -.125)); } 75% { transform: translate(0, 0); } 87.5% { transform: translate(calc(var(--loader-size, 96px) * .177), calc(var(--loader-size, 96px) * .125)); } 100% { transform: translate(calc(var(--loader-size, 96px) * .25), 0); } }

